"use client";

import type { CSSProperties } from "react";
import type { TextElement } from "@easyprint/shared/template/document";

export const EDITOR_UNIT_SCALE = 6;
export const MILLIMETERS_PER_POINT = 25.4 / 72;
export const POINTS_PER_MILLIMETER = 72 / 25.4;

export const TEXT_FONT_OPTIONS = [
  { value: "\"IBM Plex Sans\", \"Segoe UI\", sans-serif", label: "IBM Plex Sans" },
  { value: "\"IBM Plex Serif\", Georgia, serif", label: "IBM Plex Serif" },
  { value: "\"Segoe UI\", Arial, sans-serif", label: "Segoe UI" },
  { value: "Arial, Helvetica, sans-serif", label: "Arial" },
  { value: "\"Trebuchet MS\", sans-serif", label: "Trebuchet" },
  { value: "\"Times New Roman\", Times, serif", label: "Times New Roman" },
  { value: "Georgia, serif", label: "Georgia" },
  { value: "\"Courier New\", monospace", label: "Courier New" },
  { value: "\"IBM Plex Mono\", \"Courier New\", monospace", label: "IBM Plex Mono" }
] as const;

const MIN_TEXT_HEIGHT_UNITS = 6;
let measurementCanvas: HTMLCanvasElement | null = null;

export const pointsToMillimeters = (points: number) => points * MILLIMETERS_PER_POINT;
export const millimetersToPoints = (millimeters: number) => millimeters * POINTS_PER_MILLIMETER;
export const getScaledTextFontSize = (points: number, pixelsPerMillimeter: number) =>
  pointsToMillimeters(points) * pixelsPerMillimeter;

const normalizeContent = (value: string) => value.replace(/\r\n/g, "\n");
const countOccurrences = (value: string, pattern: RegExp) => (value.match(pattern) ?? []).length;

const getMeasurementContext = () => {
  if (typeof document === "undefined") {
    return null;
  }

  if (!measurementCanvas) {
    measurementCanvas = document.createElement("canvas");
  }

  return measurementCanvas.getContext("2d");
};

const buildFontDescriptor = (element: TextElement, fontSizePx: number) =>
  `${element.fontStyle} ${element.fontWeight} ${fontSizePx}px ${element.fontFamily}`;

const getBlockUnitSize = (value: number | undefined, scale: number, physical: boolean) =>
  physical ? `${value ?? 0}mm` : (value ?? 0) * scale;

const getSpacingUnitSize = (value: number | undefined, scale: number, physical: boolean) =>
  physical ? `${pointsToMillimeters(value ?? 0)}mm` : getScaledTextFontSize(value ?? 0, scale);

const getHorizontalPaddingUnits = (element: TextElement) =>
  (element.paddingLeft ?? 0) + (element.paddingRight ?? 0);

const getVerticalPaddingUnits = (element: TextElement) =>
  (element.paddingTop ?? 0) + (element.paddingBottom ?? 0);

const measureTextWidth = (
  value: string,
  context: CanvasRenderingContext2D,
  element: TextElement,
  letterSpacingPx: number,
  wordSpacingPx: number
) => {
  const rawWidth = context.measureText(value).width;
  const letterSpacingWidth = Math.max(0, value.length - 1) * letterSpacingPx;
  const wordSpacingWidth = countOccurrences(value, /\s/g) * wordSpacingPx;
  return rawWidth + letterSpacingWidth + wordSpacingWidth;
};

const breakLongToken = (
  token: string,
  maxWidthPx: number,
  context: CanvasRenderingContext2D,
  element: TextElement,
  letterSpacingPx: number,
  wordSpacingPx: number
) => {
  if (measureTextWidth(token, context, element, letterSpacingPx, wordSpacingPx) <= maxWidthPx) {
    return [token];
  }

  const pieces: string[] = [];
  let current = "";

  for (const character of token) {
    const next = `${current}${character}`;
    if (
      current &&
      measureTextWidth(next, context, element, letterSpacingPx, wordSpacingPx) > maxWidthPx
    ) {
      pieces.push(current);
      current = character;
      continue;
    }

    current = next;
  }

  if (current) {
    pieces.push(current);
  }

  return pieces;
};

const wrapLine = (
  line: string,
  maxWidthPx: number,
  context: CanvasRenderingContext2D,
  element: TextElement,
  letterSpacingPx: number,
  wordSpacingPx: number
) => {
  if (!line) {
    return [""];
  }

  const tokens = line.split(/(\s+)/).filter((token) => token.length > 0);
  const wrapped: string[] = [];
  let current = "";

  for (const token of tokens) {
    const segments =
      measureTextWidth(token, context, element, letterSpacingPx, wordSpacingPx) > maxWidthPx &&
      !/^\s+$/.test(token)
        ? breakLongToken(token, maxWidthPx, context, element, letterSpacingPx, wordSpacingPx)
        : [token];

    for (const segment of segments) {
      const next = `${current}${segment}`;
      if (
        current &&
        measureTextWidth(next, context, element, letterSpacingPx, wordSpacingPx) > maxWidthPx
      ) {
        wrapped.push(current.trimEnd());
        current = segment.trimStart();
        continue;
      }

      current = next;
    }
  }

  wrapped.push(current.trimEnd());
  return wrapped.filter((entry, index) => entry.length > 0 || index === 0);
};

export const getTextElementStyle = (
  element: TextElement,
  scale = 1,
  options?: { physical?: boolean }
): CSSProperties => {
  const physical = Boolean(options?.physical);
  const isJustified = element.align === "justify";
  const wrapMode = element.wrapMode ?? "wrap";

  return {
    width: "100%",
    height: "100%",
    overflow: element.overflowMode ?? "hidden",
    boxSizing: "border-box",
    paddingTop: getBlockUnitSize(element.paddingTop, scale, physical),
    paddingRight: getBlockUnitSize(element.paddingRight, scale, physical),
    paddingBottom: getBlockUnitSize(element.paddingBottom, scale, physical),
    paddingLeft: getBlockUnitSize(element.paddingLeft, scale, physical),
    color: element.color,
    fontFamily: element.fontFamily,
    fontSize: physical
      ? `${pointsToMillimeters(element.fontSize)}mm`
      : getScaledTextFontSize(element.fontSize, scale),
    fontWeight: element.fontWeight,
    fontStyle: element.fontStyle,
    textDecoration: element.textDecoration,
    lineHeight: element.lineHeight,
    letterSpacing: getSpacingUnitSize(element.letterSpacing, scale, physical),
    wordSpacing: getSpacingUnitSize(element.wordSpacing, scale, physical),
    textAlign: element.align,
    textAlignLast: isJustified ? "left" : undefined,
    textJustify: isJustified ? "inter-word" : undefined,
    hyphens: isJustified ? "auto" : undefined,
    textIndent: getBlockUnitSize(element.textIndent, scale, physical),
    whiteSpace: wrapMode === "nowrap" ? "pre" : "pre-wrap",
    overflowWrap: wrapMode === "nowrap" ? "normal" : isJustified ? "break-word" : "anywhere",
    wordBreak: wrapMode === "nowrap" ? "normal" : isJustified ? "normal" : "break-word",
    display: "block"
  };
};

export const measureTextElementHeight = (
  element: TextElement,
  content: string,
  widthUnits = element.width,
  unitScale = EDITOR_UNIT_SCALE
) => {
  const context = getMeasurementContext();
  if (!context) {
    return Math.max(element.height, MIN_TEXT_HEIGHT_UNITS);
  }

  const fontSizePx = Math.max(1, getScaledTextFontSize(element.fontSize, unitScale));
  const horizontalPaddingPx = getHorizontalPaddingUnits(element) * unitScale;
  const verticalPaddingPx = getVerticalPaddingUnits(element) * unitScale;
  const maxWidthPx = Math.max(fontSizePx, widthUnits * unitScale - horizontalPaddingPx);
  const letterSpacingPx = getScaledTextFontSize(element.letterSpacing ?? 0, unitScale);
  const wordSpacingPx = getScaledTextFontSize(element.wordSpacing ?? 0, unitScale);
  context.font = buildFontDescriptor(element, fontSizePx);

  const wrappedLines =
    (element.wrapMode ?? "wrap") === "nowrap"
      ? normalizeContent(content).split("\n")
      : normalizeContent(content)
          .split("\n")
          .flatMap((line, index) =>
            wrapLine(
              line,
              index === 0 ? Math.max(fontSizePx, maxWidthPx - (element.textIndent ?? 0) * unitScale) : maxWidthPx,
              context,
              element,
              letterSpacingPx,
              wordSpacingPx
            )
          );

  const lineCount = Math.max(1, wrappedLines.length);
  const heightPx =
    lineCount * fontSizePx * element.lineHeight + fontSizePx * 0.35 + verticalPaddingPx;
  const heightUnits = Number((heightPx / unitScale).toFixed(2));

  return Math.max(MIN_TEXT_HEIGHT_UNITS, heightUnits);
};
