"use client";

import {
  type ImageElement,
  type LabelElement,
  type LabelUnit,
  type TextElement
} from "@easyprint/shared/template/document";
import {
  getBarcodeMinimumSize,
  normalizeBarcodeText,
  validateBarcodeValue,
  validateQrCodeValue
} from "@easyprint/shared/template/barcode";
import { getMissingRequiredFields } from "@easyprint/shared/template/render";
import type { TemplateApprovalItem, TemplateVersionItem } from "../../lib/api";
import { uploadAsset } from "../../lib/api";
import { measureTextElementHeight, TEXT_FONT_OPTIONS } from "../../lib/editor-text";
import { clampElementPositionToDocument } from "../../lib/element-movement-bounds";
import { useEditorStore } from "../../lib/editor-store";
import { loadStoredSession } from "../../lib/session";
import {
  findLabelFormatByDimensions,
  getLabelFormatById,
  LABEL_FORMAT_CATEGORIES,
  LABEL_FORMATS
} from "../../lib/label-format-registry";
import {
  getCategoryDefinition,
  MODEL_CATEGORIES,
  normalizeModelCategory,
  type ModelCategory
} from "../../lib/template-library";

export function EditorProperties({
  readOnly = false,
  canManageAssets = false,
  versions = [],
  approvals = [],
  onRollback,
  rollbackPending = false,
  onCreateVersion,
  createVersionPending = false
}: {
  readOnly?: boolean;
  canManageAssets?: boolean;
  versions?: TemplateVersionItem[];
  approvals?: TemplateApprovalItem[];
  onRollback?: (version: number) => void;
  rollbackPending?: boolean;
  onCreateVersion?: () => void;
  createVersionPending?: boolean;
}) {
  const {
    history,
    selectedElementId,
    patchElement,
    patchDocument,
    patchTemplate,
    patchMetadata,
    addTemplateDataField,
    patchTemplateDataField,
    removeTemplateDataField,
    duplicateSelectedElement,
    toggleSelectedLock,
    rotateSelectedElement,
    moveSelectedLayer,
    alignSelectedElement
  } = useEditorStore();
  const document = history.present;
  const selectedElement = document.elements.find((element) => element.id === selectedElementId);
  const elementReadOnly = readOnly || selectedElement?.locked;
  const missingRequiredFields = getMissingRequiredFields(document);
  const selectedCategory =
    normalizeModelCategory(document.metadata.category) ?? "doces";
  const metadataFormatId =
    typeof document.metadata.formatId === "string" ? document.metadata.formatId : undefined;
  const selectedLabelFormat =
    getLabelFormatById(metadataFormatId) ??
    (document.document.unit === "mm"
      ? findLabelFormatByDimensions(document.document.width, document.document.height)
      : undefined);
  const selectedBarcodeValue =
    selectedElement?.type === "barcode"
      ? normalizeBarcodeText(selectedElement.format, selectedElement.value)
      : "";
  const selectedBarcodeValidation =
    selectedElement?.type === "barcode"
      ? validateBarcodeValue(selectedElement.format, selectedBarcodeValue)
      : undefined;
  const selectedBarcodeMinimumSize =
    selectedElement?.type === "barcode"
      ? getBarcodeMinimumSize(selectedElement.format)
      : undefined;
  const selectedBarcodeSizeWarning =
    selectedElement?.type === "barcode" &&
    selectedBarcodeMinimumSize &&
    (selectedElement.width < selectedBarcodeMinimumSize.widthMm ||
      selectedElement.height < selectedBarcodeMinimumSize.heightMm)
      ? `Use pelo menos ${selectedBarcodeMinimumSize.widthMm} x ${selectedBarcodeMinimumSize.heightMm} mm para leitura confiavel.`
      : undefined;
  const selectedQrValidation =
    selectedElement?.type === "qrcode"
      ? validateQrCodeValue(selectedElement.value)
      : undefined;

  const patchSelectedElement = (patch: Partial<LabelElement>) => {
    if (!selectedElement) return;

    if (selectedElement.type === "text") {
      const textPatch = patch as Partial<TextElement>;
      const nextElement = { ...selectedElement, ...patch } as TextElement;
      const shouldReflowText =
        textPatch.text !== undefined ||
        textPatch.width !== undefined ||
        textPatch.fontSize !== undefined ||
        textPatch.fontFamily !== undefined ||
        textPatch.fontWeight !== undefined ||
        textPatch.fontStyle !== undefined ||
        textPatch.textDecoration !== undefined ||
        textPatch.lineHeight !== undefined ||
        textPatch.align !== undefined ||
        textPatch.letterSpacing !== undefined ||
        textPatch.wordSpacing !== undefined ||
        textPatch.textIndent !== undefined ||
        textPatch.paddingTop !== undefined ||
        textPatch.paddingRight !== undefined ||
        textPatch.paddingBottom !== undefined ||
        textPatch.paddingLeft !== undefined ||
        textPatch.wrapMode !== undefined ||
        textPatch.overflowMode !== undefined;

      patchElement(selectedElement.id, {
        ...patch,
        ...(!("height" in patch) && shouldReflowText
          ? {
              height: measureTextElementHeight(
                nextElement,
                nextElement.text,
                nextElement.width
              )
            }
          : {})
      });
      return;
    }

    patchElement(selectedElement.id, patch);
  };

  const handleNumericField = (key: string, value: string) => {
    if (!selectedElement) return;
    const numericValue = Number(value);
    if (!Number.isFinite(numericValue)) {
      return;
    }

    const getMinimumElementSize = () => {
      if (selectedElement.type === "barcode") {
        return getBarcodeMinimumSize(selectedElement.format);
      }

      if (selectedElement.type === "qrcode") {
        return { widthMm: 8, heightMm: 8 };
      }

      if (selectedElement.type === "line") {
        return { widthMm: 4, heightMm: Math.max(0.2, selectedElement.strokeWidth || 0.2) };
      }

      if (selectedElement.type === "image") {
        return { widthMm: 3, heightMm: 3 };
      }

      return { widthMm: 4, heightMm: 4 };
    };

    const minSize = getMinimumElementSize();
    const nextPatch: Partial<LabelElement> = {};

    if (key === "x") {
      const boundedPosition = clampElementPositionToDocument(
        numericValue,
        selectedElement.y,
        selectedElement,
        document.document.width,
        document.document.height
      );
      nextPatch.x = Number(boundedPosition.x.toFixed(3));
    } else if (key === "y") {
      const boundedPosition = clampElementPositionToDocument(
        selectedElement.x,
        numericValue,
        selectedElement,
        document.document.width,
        document.document.height
      );
      nextPatch.y = Number(boundedPosition.y.toFixed(3));
    } else if (key === "width") {
      const boundedWidth = Math.min(
        Math.max(minSize.widthMm, numericValue),
        Math.max(minSize.widthMm, document.document.width - selectedElement.x)
      );
      nextPatch.width = Number(boundedWidth.toFixed(3));
      const boundedPosition = clampElementPositionToDocument(
        selectedElement.x,
        selectedElement.y,
        {
          width: nextPatch.width,
          height: selectedElement.height,
          rotation: selectedElement.rotation
        },
        document.document.width,
        document.document.height
      );
      nextPatch.x = Number(boundedPosition.x.toFixed(3));
      nextPatch.y = Number(boundedPosition.y.toFixed(3));
    } else if (key === "height") {
      const boundedHeight = Math.min(
        Math.max(minSize.heightMm, numericValue),
        Math.max(minSize.heightMm, document.document.height - selectedElement.y)
      );
      nextPatch.height = Number(boundedHeight.toFixed(3));
      const boundedPosition = clampElementPositionToDocument(
        selectedElement.x,
        selectedElement.y,
        {
          width: selectedElement.width,
          height: nextPatch.height,
          rotation: selectedElement.rotation
        },
        document.document.width,
        document.document.height
      );
      nextPatch.x = Number(boundedPosition.x.toFixed(3));
      nextPatch.y = Number(boundedPosition.y.toFixed(3));
    } else {
      (nextPatch as Record<string, number>)[key] = numericValue;
    }

    patchSelectedElement(nextPatch);
  };

  const syncDocumentFormatMetadata = (
    nextWidth: number,
    nextHeight: number,
    nextUnit: LabelUnit
  ) => {
    const inferredFormat =
      nextUnit === "mm" ? findLabelFormatByDimensions(nextWidth, nextHeight) : undefined;
    patchMetadata({ formatId: inferredFormat?.id });
  };

  const handleDocumentWidthChange = (value: string) => {
    const nextWidth = Number(value);
    patchDocument({ width: nextWidth });
    syncDocumentFormatMetadata(nextWidth, document.document.height, document.document.unit);
  };

  const handleDocumentHeightChange = (value: string) => {
    const nextHeight = Number(value);
    patchDocument({ height: nextHeight });
    syncDocumentFormatMetadata(document.document.width, nextHeight, document.document.unit);
  };

  const handleDocumentUnitChange = (value: string) => {
    const nextUnit = value as LabelUnit;
    patchDocument({ unit: nextUnit });
    syncDocumentFormatMetadata(document.document.width, document.document.height, nextUnit);
  };

  const handleLabelFormatChange = (value: string) => {
    const nextFormat = getLabelFormatById(value);
    if (!nextFormat) {
      syncDocumentFormatMetadata(
        document.document.width,
        document.document.height,
        document.document.unit
      );
      return;
    }

    const nextOrientation =
      nextFormat.widthMm === nextFormat.heightMm
        ? document.document.orientation
        : nextFormat.widthMm > nextFormat.heightMm
          ? "landscape"
          : "portrait";

    patchDocument({
      width: nextFormat.widthMm,
      height: nextFormat.heightMm,
      unit: "mm",
      orientation: nextOrientation
    });
    patchMetadata({ formatId: nextFormat.id });
  };

  return (
    <aside className="editor-sidebar editor-sidebar--inspector">
      <div className="editor-sidebar__header">
        <div className="muted" style={{ fontSize: 12, marginBottom: 8 }}>
          Propriedades
        </div>
        <strong>{selectedElement ? selectedElement.name : "Documento"}</strong>
      </div>

      <div className="editor-sidebar__body" style={{ display: "grid", gap: 18, alignContent: "start" }}>
      <section className="panel" style={{ padding: 16, borderRadius: 18, boxShadow: "none" }}>
        <div style={{ display: "grid", gap: 12 }}>
          <label>
            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
              Etiqueta / formato oficial
            </div>
            <select
              value={selectedLabelFormat?.id ?? ""}
              disabled={readOnly}
              onChange={(event) => handleLabelFormatChange(event.target.value)}
            >
              <option value="">Tamanho manual</option>
              {LABEL_FORMAT_CATEGORIES.map((category) => {
                const formats = LABEL_FORMATS.filter((format) => format.category === category.id);
                if (formats.length === 0) return null;

                return (
                  <optgroup key={category.id} label={category.label}>
                    {formats.map((format) => (
                      <option key={format.id} value={format.id}>
                        {format.name} ({format.widthMm} x {format.heightMm} mm)
                      </option>
                    ))}
                  </optgroup>
                );
              })}
            </select>
          </label>
          <div
            style={{
              padding: 12,
              borderRadius: 14,
              background: "rgba(15, 118, 110, 0.08)",
              border: "1px solid rgba(15, 118, 110, 0.12)",
              fontSize: 13,
              color: "var(--text)"
            }}
          >
            {selectedLabelFormat
              ? `Etiqueta ativa: ${selectedLabelFormat.name}. Ao escolher um formato oficial, o editor aplica largura, altura e orientacao automaticamente.`
              : "Este documento esta em tamanho manual. Escolha uma etiqueta oficial para padronizar medidas e orientacao no editor."}
          </div>
          <label>
            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
              Nome do template
            </div>
            <input
              value={document.name}
              disabled={readOnly}
              onChange={(event) => patchTemplate({ name: event.target.value })}
            />
          </label>
          <label>
            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
              Largura
            </div>
            <input
              value={document.document.width}
              type="number"
              disabled={readOnly}
              onChange={(event) => handleDocumentWidthChange(event.target.value)}
            />
          </label>
          <label>
            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
              Altura
            </div>
            <input
              value={document.document.height}
              type="number"
              disabled={readOnly}
              onChange={(event) => handleDocumentHeightChange(event.target.value)}
            />
          </label>
          <label>
            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
              Unidade
            </div>
            <select
              value={document.document.unit}
              disabled={readOnly}
              onChange={(event) => handleDocumentUnitChange(event.target.value)}
            >
              <option value="mm">mm</option>
              <option value="cm">cm</option>
              <option value="in">in</option>
              <option value="px">px</option>
            </select>
          </label>
          <label>
            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
              Status
            </div>
            <select
              value={document.status}
              disabled
              onChange={() => undefined}
            >
              <option value="draft">draft</option>
              <option value="in_review">in_review</option>
              <option value="approved">approved</option>
              <option value="published">published</option>
              <option value="archived">archived</option>
            </select>
          </label>
          <label>
            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
              Categoria do modelo
            </div>
            <select
              value={selectedCategory}
              disabled={readOnly}
              onChange={(event) =>
                patchMetadata({ category: event.target.value as ModelCategory })
              }
            >
              {MODEL_CATEGORIES.map((category) => (
                <option key={category} value={category}>
                  {getCategoryDefinition(category).label}
                </option>
              ))}
            </select>
          </label>
          <div
            style={{
              padding: 12,
              borderRadius: 14,
              background: getCategoryDefinition(selectedCategory).soft,
              color: getCategoryDefinition(selectedCategory).accent,
              fontSize: 13,
              fontWeight: 600
            }}
          >
            {getCategoryDefinition(selectedCategory).description}
          </div>
        </div>
      </section>

      {!selectedElement ? (
        <>
          <section className="panel" style={{ padding: 16, borderRadius: 18, boxShadow: "none" }}>
            <div style={{ display: "grid", gap: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", gap: 12 }}>
                <div>
                  <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                    Campos dinamicos
                  </div>
                  <strong>Data schema</strong>
                </div>
                <button disabled={readOnly} onClick={() => addTemplateDataField()}>
                  Novo campo
                </button>
              </div>

              {missingRequiredFields.length > 0 ? (
                <div
                  style={{
                    display: "grid",
                    gap: 6,
                    padding: 12,
                    borderRadius: 14,
                    background: "rgba(245, 158, 11, 0.08)",
                    border: "1px solid rgba(245, 158, 11, 0.18)"
                  }}
                >
                  <strong style={{ fontSize: 13 }}>Campos obrigatorios sem preview completo</strong>
                  <div className="muted" style={{ fontSize: 12 }}>
                    {missingRequiredFields.map((field) => field.label).join(", ")}
                  </div>
                </div>
              ) : null}

              {document.dataSchema.length === 0 ? (
                <div className="muted" style={{ fontSize: 13 }}>
                  Nenhum campo dinamico configurado ainda.
                </div>
              ) : null}

              {document.dataSchema.map((field) => (
                <div
                  key={field.key}
                  style={{
                    display: "grid",
                    gap: 10,
                    padding: 12,
                    borderRadius: 14,
                    border: "1px solid var(--line)"
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", gap: 10 }}>
                    <strong>{field.label}</strong>
                    <button disabled={readOnly} onClick={() => removeTemplateDataField(field.key)}>
                      Remover
                    </button>
                  </div>
                  <label>
                    <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                      Chave
                    </div>
                    <input
                      value={field.key}
                      disabled={readOnly}
                      onChange={(event) =>
                        patchTemplateDataField(field.key, { key: event.target.value.trim() || field.key })
                      }
                    />
                  </label>
                  <label>
                    <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                      Rotulo
                    </div>
                    <input
                      value={field.label}
                      disabled={readOnly}
                      onChange={(event) =>
                        patchTemplateDataField(field.key, { label: event.target.value })
                      }
                    />
                  </label>
                  <label>
                    <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                      Descricao
                    </div>
                    <input
                      value={field.description ?? ""}
                      disabled={readOnly}
                      onChange={(event) =>
                        patchTemplateDataField(field.key, { description: event.target.value })
                      }
                    />
                  </label>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                    <label>
                      <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                        Tipo
                      </div>
                      <select
                        value={field.type}
                        disabled={readOnly}
                        onChange={(event) =>
                          patchTemplateDataField(field.key, {
                            type: event.target.value as typeof field.type
                          })
                        }
                      >
                        <option value="text">text</option>
                        <option value="number">number</option>
                        <option value="date">date</option>
                        <option value="boolean">boolean</option>
                      </select>
                    </label>
                    <label>
                      <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                        Formato
                      </div>
                      <select
                        value={field.formatType ?? "text"}
                        disabled={readOnly}
                        onChange={(event) =>
                          patchTemplateDataField(field.key, {
                            formatType: event.target.value as NonNullable<typeof field.formatType>
                          })
                        }
                      >
                        <option value="text">text</option>
                        <option value="date">date</option>
                        <option value="currency">currency</option>
                        <option value="uppercase">uppercase</option>
                        <option value="lowercase">lowercase</option>
                      </select>
                    </label>
                  </div>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                    <label>
                      <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                        Exemplo
                      </div>
                      <input
                        value={field.sampleValue === undefined ? "" : String(field.sampleValue)}
                        disabled={readOnly}
                        onChange={(event) =>
                          patchTemplateDataField(field.key, { sampleValue: event.target.value })
                        }
                      />
                    </label>
                    <label>
                      <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                        Fallback
                      </div>
                      <input
                        value={field.fallbackValue ?? ""}
                        disabled={readOnly}
                        onChange={(event) =>
                          patchTemplateDataField(field.key, { fallbackValue: event.target.value })
                        }
                      />
                    </label>
                  </div>
                  <label style={{ display: "flex", gap: 8, alignItems: "center" }}>
                    <input
                      type="checkbox"
                      checked={field.required}
                      disabled={readOnly}
                      onChange={(event) =>
                        patchTemplateDataField(field.key, { required: event.target.checked })
                      }
                    />
                    Obrigatorio no preview
                  </label>
                </div>
              ))}
            </div>
          </section>

          {versions.length > 0 ? (
            <section className="panel" style={{ padding: 16, borderRadius: 18, boxShadow: "none" }}>
              <div style={{ display: "grid", gap: 12 }}>
                <div style={{ display: "flex", justifyContent: "space-between", gap: 12 }}>
                  <div>
                    <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                      Historico de versoes
                    </div>
                    <strong>Versoes recentes</strong>
                  </div>
                  <button disabled={readOnly || createVersionPending || !onCreateVersion} onClick={() => onCreateVersion?.()}>
                    Nova versao
                  </button>
                </div>

                {versions.slice(0, 6).map((version) => (
                  <div
                    key={version.id}
                    style={{
                      display: "grid",
                      gap: 8,
                      padding: 12,
                      borderRadius: 14,
                      border: "1px solid var(--line)"
                    }}
                  >
                    <div style={{ display: "flex", justifyContent: "space-between", gap: 10 }}>
                      <strong>v{version.version}</strong>
                      <span className="muted" style={{ fontSize: 12 }}>
                        {version.status.toLowerCase()}
                      </span>
                    </div>
                    <div className="muted" style={{ fontSize: 12 }}>
                      {new Date(version.createdAt).toLocaleString("pt-BR")}
                    </div>
                    {version.notes ? (
                      <div className="muted" style={{ fontSize: 12 }}>
                        {version.notes}
                      </div>
                    ) : null}
                    {version.compareSummary ? (
                      <div className="muted" style={{ fontSize: 12 }}>
                        delta elementos {version.compareSummary.elementsDelta >= 0 ? "+" : ""}
                        {version.compareSummary.elementsDelta} | delta campos{" "}
                        {version.compareSummary.dataFieldsDelta >= 0 ? "+" : ""}
                        {version.compareSummary.dataFieldsDelta}
                        {version.compareSummary.sizeChanged ? " | tamanho alterado" : ""}
                      </div>
                    ) : null}
                    <div>
                      <button
                        disabled={readOnly || rollbackPending || !onRollback}
                        onClick={() => onRollback?.(version.version)}
                      >
                        Restaurar esta versao
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          ) : null}

          {approvals.length > 0 ? (
            <section className="panel" style={{ padding: 16, borderRadius: 18, boxShadow: "none" }}>
              <div style={{ display: "grid", gap: 12 }}>
                <div>
                  <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                    Governanca
                  </div>
                  <strong>Aprovacoes recentes</strong>
                </div>

                {approvals.slice(0, 5).map((approval) => (
                  <div
                    key={approval.id}
                    style={{
                      display: "grid",
                      gap: 8,
                      padding: 12,
                      borderRadius: 14,
                      border: "1px solid var(--line)"
                    }}
                  >
                    <div style={{ display: "flex", justifyContent: "space-between", gap: 10 }}>
                      <strong>{approval.status.toLowerCase()}</strong>
                      <span className="muted" style={{ fontSize: 12 }}>
                        {new Date(approval.requestedAt).toLocaleString("pt-BR")}
                      </span>
                    </div>
                    <div className="muted" style={{ fontSize: 12 }}>
                      solicitado por {approval.requestedBy?.name ?? "usuario"}
                    </div>
                    {approval.requestNotes ? (
                      <div className="muted" style={{ fontSize: 12 }}>
                        {approval.requestNotes}
                      </div>
                    ) : null}
                    {approval.decisionNotes ? (
                      <div className="muted" style={{ fontSize: 12 }}>
                        decisao: {approval.decisionNotes}
                      </div>
                    ) : null}
                    {approval.signatures?.length ? (
                      <div className="muted" style={{ fontSize: 12 }}>
                        assinatura: {approval.signatures[0]?.action}
                      </div>
                    ) : null}
                  </div>
                ))}
              </div>
            </section>
          ) : null}
        </>
      ) : null}

      {selectedElement ? (
        <section className="panel" style={{ padding: 16, borderRadius: 18, boxShadow: "none" }}>
          <div style={{ display: "grid", gap: 12 }}>
            <div
              style={{
                display: "grid",
                gap: 8,
                padding: 12,
                borderRadius: 14,
                background: "rgba(15,23,42,0.03)"
              }}
            >
              <div className="muted" style={{ fontSize: 12 }}>
                Acoes rapidas
              </div>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <button disabled={readOnly} onClick={() => duplicateSelectedElement()}>
                  Duplicar
                </button>
                <button disabled={readOnly} onClick={() => toggleSelectedLock()}>
                  {selectedElement.locked ? "Desbloquear" : "Bloquear"}
                </button>
              </div>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <button disabled={elementReadOnly} onClick={() => moveSelectedLayer("backward")}>
                  Camada -
                </button>
                <button disabled={elementReadOnly} onClick={() => moveSelectedLayer("forward")}>
                  Camada +
                </button>
                <button disabled={elementReadOnly} onClick={() => moveSelectedLayer("back")}>
                  Para tras
                </button>
                <button disabled={elementReadOnly} onClick={() => moveSelectedLayer("front")}>
                  Para frente
                </button>
              </div>
            </div>

            <label>
              <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                Posicao X
              </div>
              <input
                value={selectedElement.x}
                type="number"
                step={0.1}
                disabled={elementReadOnly}
                onChange={(event) => handleNumericField("x", event.target.value)}
              />
            </label>
            <label>
              <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                Posicao Y
              </div>
              <input
                value={selectedElement.y}
                type="number"
                step={0.1}
                disabled={elementReadOnly}
                onChange={(event) => handleNumericField("y", event.target.value)}
              />
            </label>
            <label>
              <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                Largura
              </div>
              <input
                value={selectedElement.width}
                type="number"
                step={0.1}
                min={0}
                disabled={elementReadOnly}
                onChange={(event) => handleNumericField("width", event.target.value)}
              />
            </label>
            <label>
              <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                Altura
              </div>
              <input
                value={selectedElement.height}
                type="number"
                step={0.1}
                min={0}
                disabled={elementReadOnly}
                onChange={(event) => handleNumericField("height", event.target.value)}
              />
            </label>
            <label>
              <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                Rotacao
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "44px 1fr 44px", gap: 8 }}>
                <button disabled={elementReadOnly} onClick={() => rotateSelectedElement(-15)}>
                  -15
                </button>
                <input
                  value={selectedElement.rotation}
                  type="number"
                  disabled={elementReadOnly}
                  onChange={(event) =>
                    patchElement(
                      selectedElement.id,
                      { rotation: Number(event.target.value) } as Partial<LabelElement>
                    )
                  }
                />
                <button disabled={elementReadOnly} onClick={() => rotateSelectedElement(15)}>
                  +15
                </button>
              </div>
            </label>
            <div style={{ display: "grid", gap: 8 }}>
              <div className="muted" style={{ fontSize: 12 }}>
                Alinhamento no canvas
              </div>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <button disabled={elementReadOnly} onClick={() => alignSelectedElement("left")}>
                  Esq
                </button>
                <button disabled={elementReadOnly} onClick={() => alignSelectedElement("center")}>
                  Centro H
                </button>
                <button disabled={elementReadOnly} onClick={() => alignSelectedElement("right")}>
                  Dir
                </button>
                <button disabled={elementReadOnly} onClick={() => alignSelectedElement("top")}>
                  Topo
                </button>
                <button disabled={elementReadOnly} onClick={() => alignSelectedElement("middle")}>
                  Centro V
                </button>
                <button disabled={elementReadOnly} onClick={() => alignSelectedElement("bottom")}>
                  Base
                </button>
              </div>
            </div>
            <label style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <input
                type="checkbox"
                checked={selectedElement.visible}
                disabled={elementReadOnly}
                onChange={(event) =>
                  patchSelectedElement({ visible: event.target.checked } as Partial<LabelElement>)
                }
              />
              <span>Visivel</span>
            </label>

            {selectedElement.type === "text" ? (
              <>
                <label>
                  <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                    Conteudo
                  </div>
                  <textarea
                    value={selectedElement.text}
                    rows={4}
                    disabled={elementReadOnly}
                    onChange={(event) =>
                      patchSelectedElement({ text: event.target.value } as Partial<LabelElement>)
                    }
                    style={{ minHeight: 108 }}
                  />
                </label>
                <section
                  style={{
                    display: "grid",
                    gap: 12,
                    padding: 12,
                    borderRadius: 14,
                    background: "rgba(15,23,42,0.03)"
                  }}
                >
                  <div className="muted" style={{ fontSize: 12 }}>
                    Tipografia basica
                  </div>

                  <label>
                    <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                      Fonte
                    </div>
                    <select
                      value={selectedElement.fontFamily}
                      disabled={elementReadOnly}
                      onChange={(event) =>
                        patchSelectedElement({ fontFamily: event.target.value } as Partial<LabelElement>)
                      }
                    >
                      {TEXT_FONT_OPTIONS.map((font) => (
                        <option key={font.value} value={font.value}>
                          {font.label}
                        </option>
                      ))}
                    </select>
                  </label>

                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10 }}>
                    <label>
                      <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                        Tamanho (pt)
                      </div>
                      <input
                        type="number"
                        min={6}
                        max={96}
                        value={selectedElement.fontSize}
                        disabled={elementReadOnly}
                        onChange={(event) =>
                          patchSelectedElement({ fontSize: Number(event.target.value) } as Partial<LabelElement>)
                        }
                      />
                    </label>
                    <label>
                      <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                        Entrelinhamento
                      </div>
                      <input
                        type="number"
                        min={0.8}
                        max={2.4}
                        step={0.05}
                        value={selectedElement.lineHeight}
                        disabled={elementReadOnly}
                        onChange={(event) =>
                          patchSelectedElement({ lineHeight: Number(event.target.value) } as Partial<LabelElement>)
                        }
                      />
                    </label>
                    <label>
                      <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                        Cor
                      </div>
                      <input
                        type="color"
                        value={selectedElement.color}
                        disabled={elementReadOnly}
                        onChange={(event) =>
                          patchSelectedElement({ color: event.target.value } as Partial<LabelElement>)
                        }
                        style={{ minHeight: 44, padding: 6 }}
                      />
                    </label>
                  </div>

                  <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8 }}>
                    <button
                      type="button"
                      disabled={elementReadOnly}
                      onClick={() =>
                        patchSelectedElement({
                          fontWeight: selectedElement.fontWeight >= 700 ? 500 : 700
                        } as Partial<LabelElement>)
                      }
                      style={{
                        fontWeight: 700,
                        background:
                          selectedElement.fontWeight >= 700 ? "var(--primary-soft)" : "#ffffff"
                      }}
                    >
                      B
                    </button>
                    <button
                      type="button"
                      disabled={elementReadOnly}
                      onClick={() =>
                        patchSelectedElement({
                          fontStyle: selectedElement.fontStyle === "italic" ? "normal" : "italic"
                        } as Partial<LabelElement>)
                      }
                      style={{
                        fontStyle: "italic",
                        background:
                          selectedElement.fontStyle === "italic" ? "var(--primary-soft)" : "#ffffff"
                      }}
                    >
                      I
                    </button>
                    <button
                      type="button"
                      disabled={elementReadOnly}
                      onClick={() =>
                        patchSelectedElement({
                          textDecoration:
                            selectedElement.textDecoration === "underline" ? "none" : "underline"
                        } as Partial<LabelElement>)
                      }
                      style={{
                        textDecoration: "underline",
                        background:
                          selectedElement.textDecoration === "underline"
                            ? "var(--primary-soft)"
                            : "#ffffff"
                      }}
                    >
                      U
                    </button>
                  </div>

                  <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 8 }}>
                    {[
                      { value: "left", label: "Esq" },
                      { value: "center", label: "Centro" },
                      { value: "right", label: "Dir" },
                      { value: "justify", label: "Just" }
                    ].map((item) => (
                      <button
                        key={item.value}
                        type="button"
                        disabled={elementReadOnly}
                        onClick={() =>
                          patchSelectedElement({ align: item.value as TextElement["align"] } as Partial<LabelElement>)
                        }
                        style={{
                          background:
                            selectedElement.align === item.value ? "var(--primary-soft)" : "#ffffff"
                        }}
                      >
                        {item.label}
                      </button>
                    ))}
                  </div>

                  <details
                    style={{
                      border: "1px solid var(--line)",
                      borderRadius: 12,
                      background: "#ffffff",
                      padding: 10
                    }}
                  >
                    <summary style={{ cursor: "pointer", fontWeight: 600 }}>
                      Tipografia avancada
                    </summary>

                    <div style={{ display: "grid", gap: 12, marginTop: 12 }}>
                      <div
                        style={{
                          display: "grid",
                          gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
                          gap: 10
                        }}
                      >
                        <label>
                          <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                            Espaco entre letras (pt)
                          </div>
                          <input
                            type="number"
                            step={0.1}
                            value={selectedElement.letterSpacing ?? 0}
                            disabled={elementReadOnly}
                            onChange={(event) =>
                              patchSelectedElement({
                                letterSpacing: Number(event.target.value)
                              } as Partial<LabelElement>)
                            }
                          />
                        </label>

                        <label>
                          <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                            Espaco entre palavras (pt)
                          </div>
                          <input
                            type="number"
                            step={0.1}
                            value={selectedElement.wordSpacing ?? 0}
                            disabled={elementReadOnly}
                            onChange={(event) =>
                              patchSelectedElement({
                                wordSpacing: Number(event.target.value)
                              } as Partial<LabelElement>)
                            }
                          />
                        </label>

                        <label>
                          <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                            Recuo da primeira linha (mm)
                          </div>
                          <input
                            type="number"
                            step={0.1}
                            value={selectedElement.textIndent ?? 0}
                            disabled={elementReadOnly}
                            onChange={(event) =>
                              patchSelectedElement({
                                textIndent: Number(event.target.value)
                              } as Partial<LabelElement>)
                            }
                          />
                        </label>

                        <label>
                          <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                            Quebra de linha
                          </div>
                          <select
                            value={selectedElement.wrapMode ?? "wrap"}
                            disabled={elementReadOnly}
                            onChange={(event) =>
                              patchSelectedElement({
                                wrapMode: event.target.value as TextElement["wrapMode"]
                              } as Partial<LabelElement>)
                            }
                          >
                            <option value="wrap">Quebrar linhas</option>
                            <option value="nowrap">Manter em linha unica</option>
                          </select>
                        </label>

                        <label>
                          <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                            Overflow do bloco
                          </div>
                          <select
                            value={selectedElement.overflowMode ?? "hidden"}
                            disabled={elementReadOnly}
                            onChange={(event) =>
                              patchSelectedElement({
                                overflowMode: event.target.value as TextElement["overflowMode"]
                              } as Partial<LabelElement>)
                            }
                          >
                            <option value="hidden">Cortar no bloco</option>
                            <option value="visible">Permitir exceder</option>
                          </select>
                        </label>
                      </div>

                      <div style={{ display: "grid", gap: 8 }}>
                        <div className="muted" style={{ fontSize: 12 }}>
                          Padding interno do texto (mm)
                        </div>
                        <div
                          style={{
                            display: "grid",
                            gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
                            gap: 10
                          }}
                        >
                          <label>
                            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                              Topo
                            </div>
                            <input
                              type="number"
                              step={0.1}
                              min={0}
                              value={selectedElement.paddingTop ?? 0}
                              disabled={elementReadOnly}
                              onChange={(event) =>
                                patchSelectedElement({
                                  paddingTop: Number(event.target.value)
                                } as Partial<LabelElement>)
                              }
                            />
                          </label>
                          <label>
                            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                              Direita
                            </div>
                            <input
                              type="number"
                              step={0.1}
                              min={0}
                              value={selectedElement.paddingRight ?? 0}
                              disabled={elementReadOnly}
                              onChange={(event) =>
                                patchSelectedElement({
                                  paddingRight: Number(event.target.value)
                                } as Partial<LabelElement>)
                              }
                            />
                          </label>
                          <label>
                            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                              Base
                            </div>
                            <input
                              type="number"
                              step={0.1}
                              min={0}
                              value={selectedElement.paddingBottom ?? 0}
                              disabled={elementReadOnly}
                              onChange={(event) =>
                                patchSelectedElement({
                                  paddingBottom: Number(event.target.value)
                                } as Partial<LabelElement>)
                              }
                            />
                          </label>
                          <label>
                            <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                              Esquerda
                            </div>
                            <input
                              type="number"
                              step={0.1}
                              min={0}
                              value={selectedElement.paddingLeft ?? 0}
                              disabled={elementReadOnly}
                              onChange={(event) =>
                                patchSelectedElement({
                                  paddingLeft: Number(event.target.value)
                                } as Partial<LabelElement>)
                              }
                            />
                          </label>
                        </div>
                      </div>
                    </div>
                  </details>

                  <button
                    type="button"
                    disabled={elementReadOnly}
                    onClick={() =>
                      patchSelectedElement({
                        height: measureTextElementHeight(
                          selectedElement,
                          selectedElement.text,
                          selectedElement.width
                        )
                      } as Partial<LabelElement>)
                    }
                  >
                    Ajustar caixa ao conteudo
                  </button>
                </section>
                {selectedElement.contentMode === "dynamic" ? (
                  <>
                    <label>
                      <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                        Binding
                      </div>
                      <select
                        value={selectedElement.bindingKey ?? ""}
                        disabled={elementReadOnly}
                        onChange={(event) =>
                          patchSelectedElement(
                            {
                              bindingKey: event.target.value || undefined,
                              text: event.target.value ? `{{${event.target.value}}}` : selectedElement.text
                            } as Partial<LabelElement>
                          )
                        }
                      >
                        <option value="">Selecione um campo</option>
                        {document.dataSchema.map((field) => (
                          <option key={field.key} value={field.key}>
                            {field.label} ({field.key})
                          </option>
                        ))}
                      </select>
                    </label>
                    <label>
                      <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                        Placeholder
                      </div>
                      <input
                        value={selectedElement.placeholder ?? ""}
                        disabled={elementReadOnly}
                        onChange={(event) =>
                          patchSelectedElement({ placeholder: event.target.value } as Partial<LabelElement>)
                        }
                      />
                    </label>
                  </>
                ) : null}
              </>
            ) : null}

            {selectedElement.type === "barcode" ? (
              <>
                <label>
                  <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                    Valor
                  </div>
                  <input
                    value={selectedElement.value}
                    disabled={elementReadOnly}
                    onChange={(event) =>
                      patchElement(
                        selectedElement.id,
                        { value: event.target.value } as Partial<LabelElement>
                      )
                    }
                  />
                </label>
                <label>
                  <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                    Formato
                  </div>
                  <select
                    value={selectedElement.format}
                    disabled={elementReadOnly}
                    onChange={(event) =>
                      patchElement(
                        selectedElement.id,
                        { format: event.target.value } as Partial<LabelElement>
                      )
                    }
                  >
                    <option value="CODE128">CODE128</option>
                    <option value="EAN13">EAN13</option>
                    <option value="EAN8">EAN8</option>
                  </select>
                </label>
                {selectedBarcodeValidation && !selectedBarcodeValidation.valid ? (
                  <div
                    style={{
                      padding: 10,
                      borderRadius: 12,
                      border: "1px solid rgba(185, 28, 28, 0.22)",
                      background: "rgba(254, 242, 242, 0.92)",
                      color: "#991b1b",
                      fontSize: 12,
                      fontWeight: 700
                    }}
                  >
                    {selectedBarcodeValidation.message}
                  </div>
                ) : null}
                {selectedBarcodeSizeWarning ? (
                  <div
                    style={{
                      padding: 10,
                      borderRadius: 12,
                      border: "1px solid rgba(217, 119, 6, 0.22)",
                      background: "rgba(255, 251, 235, 0.92)",
                      color: "#92400e",
                      fontSize: 12,
                      fontWeight: 700
                    }}
                  >
                    {selectedBarcodeSizeWarning}
                  </div>
                ) : null}
                <label>
                  <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                    Binding
                  </div>
                  <select
                    value={selectedElement.bindingKey ?? ""}
                    disabled={elementReadOnly}
                    onChange={(event) =>
                      patchElement(
                        selectedElement.id,
                        {
                          bindingKey: event.target.value || undefined
                        } as Partial<LabelElement>
                      )
                    }
                  >
                    <option value="">Valor fixo</option>
                    {document.dataSchema.map((field) => (
                      <option key={field.key} value={field.key}>
                        {field.label} ({field.key})
                      </option>
                    ))}
                  </select>
                </label>
              </>
            ) : null}

            {selectedElement.type === "qrcode" ? (
              <>
                <label>
                  <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                    Valor
                  </div>
                  <input
                    value={selectedElement.value}
                    disabled={elementReadOnly}
                    onChange={(event) =>
                      patchElement(
                        selectedElement.id,
                        { value: event.target.value } as Partial<LabelElement>
                      )
                    }
                  />
                </label>
                {selectedQrValidation && !selectedQrValidation.valid ? (
                  <div
                    style={{
                      padding: 10,
                      borderRadius: 12,
                      border: "1px solid rgba(185, 28, 28, 0.22)",
                      background: "rgba(254, 242, 242, 0.92)",
                      color: "#991b1b",
                      fontSize: 12,
                      fontWeight: 700
                    }}
                  >
                    {selectedQrValidation.message}
                  </div>
                ) : null}
                <label>
                  <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                    Correcao
                  </div>
                  <select
                    value={selectedElement.errorCorrection}
                    disabled={elementReadOnly}
                    onChange={(event) =>
                      patchElement(
                        selectedElement.id,
                        { errorCorrection: event.target.value } as Partial<LabelElement>
                      )
                    }
                  >
                    <option value="L">L</option>
                    <option value="M">M</option>
                    <option value="Q">Q</option>
                    <option value="H">H</option>
                  </select>
                </label>
              </>
            ) : null}

            {selectedElement.type === "shape" ? (
              <label>
                <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                  Borda
                </div>
                <input
                  value={selectedElement.stroke}
                  disabled={elementReadOnly}
                  onChange={(event) =>
                    patchElement(selectedElement.id, { stroke: event.target.value } as Partial<LabelElement>)
                  }
                />
              </label>
            ) : null}

            {selectedElement.type === "image" ? (
              <section
                style={{
                  display: "grid",
                  gap: 12,
                  padding: 12,
                  borderRadius: 14,
                  background: "rgba(15,23,42,0.03)"
                }}
              >
                <div className="muted" style={{ fontSize: 12 }}>
                  Imagem
                </div>

                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                  <label>
                    <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                      Opacidade
                    </div>
                    <input
                      type="number"
                      min={0}
                      max={1}
                      step={0.05}
                      value={selectedElement.opacity}
                      disabled={elementReadOnly}
                      onChange={(event) =>
                        patchSelectedElement({
                          opacity: Math.min(1, Math.max(0, Number(event.target.value)))
                        } as Partial<LabelElement>)
                      }
                    />
                  </label>

                  <label>
                    <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                      Ajuste
                    </div>
                    <select
                      value={selectedElement.objectFit ?? (selectedElement.fit === "stretch" ? "fill" : selectedElement.fit)}
                      disabled={elementReadOnly}
                      onChange={(event) => {
                        const objectFit = event.target.value as ImageElement["objectFit"];
                        patchSelectedElement({
                          objectFit,
                          fit: objectFit === "fill" ? "stretch" : objectFit
                        } as Partial<LabelElement>);
                      }}
                    >
                      <option value="contain">Contain</option>
                      <option value="cover">Cover</option>
                      <option value="fill">Fill</option>
                    </select>
                  </label>
                </div>

                <label style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <input
                    type="checkbox"
                    checked={selectedElement.maintainAspectRatio ?? true}
                    disabled={elementReadOnly}
                    onChange={(event) =>
                      patchSelectedElement({
                        maintainAspectRatio: event.target.checked
                      } as Partial<LabelElement>)
                    }
                  />
                  <span>Manter proporcao ao redimensionar pelos cantos</span>
                </label>

                {canManageAssets && !readOnly ? (
                  <label>
                    <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>
                      Upload
                    </div>
                    <input
                      type="file"
                      accept="image/*"
                      disabled={elementReadOnly}
                      onChange={async (event) => {
                        const file = event.target.files?.[0];
                        const session = loadStoredSession();
                        if (!file || !session) return;
                        const uploaded = await uploadAsset(file, session);
                        patchElement(
                          selectedElement.id,
                          {
                            assetId: uploaded.id,
                            src: `${process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000"}${uploaded.url}`
                          } as Partial<LabelElement>
                        );
                      }}
                    />
                  </label>
                ) : null}
              </section>
            ) : null}
          </div>
        </section>
      ) : null}
      </div>
    </aside>
  );
}
