import type { LabelElement } from "@easyprint/shared/template/document";

export type ElementMovementBounds = {
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
};

const normalizeRotation = (rotation: number) => {
  if (!Number.isFinite(rotation)) {
    return 0;
  }

  const normalized = rotation % 360;
  return normalized < 0 ? normalized + 360 : normalized;
};

const collapseRange = (min: number, max: number) => {
  if (min <= max) {
    return { min, max };
  }

  // If the element is larger than the document for the current rotation,
  // keep it centered on the axis instead of producing an invalid range.
  const center = (min + max) / 2;
  return { min: center, max: center };
};

const getRotatedHalfExtents = (
  width: number,
  height: number,
  rotation: number
) => {
  const radians = (normalizeRotation(rotation) * Math.PI) / 180;
  const absCos = Math.abs(Math.cos(radians));
  const absSin = Math.abs(Math.sin(radians));

  return {
    halfWidth: (width * absCos + height * absSin) / 2,
    halfHeight: (width * absSin + height * absCos) / 2
  };
};

export const getElementMovementBounds = (
  element: Pick<LabelElement, "width" | "height" | "rotation">,
  documentWidth: number,
  documentHeight: number
): ElementMovementBounds => {
  const width = Math.max(0, element.width);
  const height = Math.max(0, element.height);
  const docWidth = Math.max(0, documentWidth);
  const docHeight = Math.max(0, documentHeight);
  const halfWidth = width / 2;
  const halfHeight = height / 2;
  const rotatedHalf = getRotatedHalfExtents(width, height, element.rotation);

  const xRange = collapseRange(
    rotatedHalf.halfWidth - halfWidth,
    docWidth - rotatedHalf.halfWidth - halfWidth
  );
  const yRange = collapseRange(
    rotatedHalf.halfHeight - halfHeight,
    docHeight - rotatedHalf.halfHeight - halfHeight
  );

  return {
    minX: xRange.min,
    maxX: xRange.max,
    minY: yRange.min,
    maxY: yRange.max
  };
};

export const clampElementPositionToDocument = (
  x: number,
  y: number,
  element: Pick<LabelElement, "width" | "height" | "rotation">,
  documentWidth: number,
  documentHeight: number
) => {
  const bounds = getElementMovementBounds(element, documentWidth, documentHeight);

  return {
    x: Math.min(bounds.maxX, Math.max(bounds.minX, x)),
    y: Math.min(bounds.maxY, Math.max(bounds.minY, y))
  };
};
