"use client";

import { Box, Button, Chip, Stack, Typography } from "@mui/material";
import { useEditorStore } from "../../lib/editor-store";

export function EditorStatusBar() {
  const {
    history,
    selectedElementId,
    zoom,
    setZoom,
    unit,
    statusMessage,
    savingState,
    gridEnabled,
    toggleGrid
  } = useEditorStore();
  const selectedElement = history.present.elements.find((element) => element.id === selectedElementId);
  const savingStateLabel =
    savingState === "saving"
      ? "salvando"
      : savingState === "saved"
        ? "sincronizado"
        : savingState === "error"
          ? "erro"
          : "pronto";

  return (
    <Box
      component="footer"
      sx={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: { xs: "flex-start", md: "center" },
        gap: 1.5,
        flexDirection: { xs: "column", md: "row" },
        px: 2.25,
        py: 0.75,
        borderTop: "1px solid rgba(15, 23, 42, 0.08)",
        bgcolor: "rgba(255,255,255,0.72)",
        backdropFilter: "blur(12px)",
        "& .MuiButton-root": {
          minWidth: 30,
          minHeight: 26,
          px: 0.75,
          py: 0.2,
          fontSize: 12,
          borderRadius: 1.5
        },
        "& .MuiChip-root": {
          height: 24
        }
      }}
    >
      <Typography variant="body2" color="text.secondary">
        {statusMessage}
      </Typography>
      <Stack direction="row" spacing={1} useFlexGap sx={{ flexWrap: "wrap" }}>
        <Button
          size="small"
          variant="outlined"
          onClick={() => setZoom(Math.max(0.35, Number((zoom - 0.1).toFixed(2))))}
        >
          -
        </Button>
        <Chip size="small" variant="outlined" label={`${Math.round(zoom * 100)}%`} />
        <Button
          size="small"
          variant="outlined"
          onClick={() => setZoom(Math.min(3, Number((zoom + 0.1).toFixed(2))))}
        >
          +
        </Button>
        <Button
          size="small"
          variant={gridEnabled ? "contained" : "outlined"}
          color={gridEnabled ? "primary" : "inherit"}
          onClick={toggleGrid}
        >
          Grade
        </Button>
        <Chip
          size="small"
          variant="outlined"
          label={gridEnabled ? "snap tecnico" : "movimento livre"}
        />
        <Chip size="small" variant="outlined" label={unit} />
        <Chip
          size="small"
          variant="outlined"
          label={
            selectedElement
              ? `x:${selectedElement.x} y:${selectedElement.y} w:${selectedElement.width} h:${selectedElement.height} r:${selectedElement.rotation}`
              : "sem selecao"
          }
        />
        <Chip
          size="small"
          color={savingState === "error" ? "error" : savingState === "saved" ? "success" : "default"}
          variant={savingState === "idle" ? "outlined" : "filled"}
          label={savingStateLabel}
        />
      </Stack>
    </Box>
  );
}
