"use client";

import Link from "next/link";
import type { ReactNode } from "react";
import {
  Box,
  Button,
  Chip,
  MenuItem,
  Stack,
  TextField,
  Typography
} from "@mui/material";
import type { LabelElement, TextElement } from "@easyprint/shared/template/document";
import { useEditorStore } from "../../lib/editor-store";
import { measureTextElementHeight, TEXT_FONT_OPTIONS } from "../../lib/editor-text";

const isTextElement = (element: LabelElement | undefined): element is TextElement =>
  Boolean(element && element.type === "text");

function ToolbarCluster({
  label,
  children
}: {
  label: string;
  children: ReactNode;
}) {
  return (
    <Stack
      direction="row"
      spacing={0.75}
      sx={{
        alignItems: "center",
        px: 0.75,
        py: 0.5,
        borderRadius: 1.5,
        border: "1px solid rgba(15, 23, 42, 0.055)",
        background: "rgba(255,255,255,0.56)",
        minHeight: 40
      }}
    >
      <Typography
        variant="caption"
        color="text.secondary"
        sx={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase" }}
      >
        {label}
      </Typography>
      <Stack
        direction="row"
        spacing={0.5}
        useFlexGap
        sx={{ flexWrap: "wrap", alignItems: "center" }}
      >
        {children}
      </Stack>
    </Stack>
  );
}

export function EditorTopbar({
  editorReadOnly,
  canUndo,
  canRedo,
  canReview,
  canApprove,
  canPublish,
  canCreateVersion,
  canPrintTest,
  showLibrary,
  showInspector,
  onToggleLibrary,
  onToggleInspector,
  onBack,
  onSave,
  onPrintTest,
  onPublish,
  onSubmitReview,
  onApprovalDecision,
  onCreateVersion
}: {
  editorReadOnly: boolean;
  canUndo: boolean;
  canRedo: boolean;
  canReview: boolean;
  canApprove: boolean;
  canPublish: boolean;
  canCreateVersion: boolean;
  canPrintTest: boolean;
  showLibrary: boolean;
  showInspector: boolean;
  onToggleLibrary: () => void;
  onToggleInspector: () => void;
  onBack: () => void;
  onSave: () => void;
  onPrintTest: () => void;
  onPublish: () => void;
  onSubmitReview: () => void;
  onApprovalDecision: (decision: "approved" | "rejected") => void;
  onCreateVersion: () => void;
}) {
  const {
    history,
    selectedElementId,
    addCanvasElement,
    patchElement,
    patchTemplate,
    duplicateSelectedElement,
    toggleSelectedLock,
    rotateSelectedElement,
    moveSelectedLayer,
    alignSelectedElement,
    undoAction,
    redoAction
  } = useEditorStore();

  const document = history.present;
  const selectedElement = document.elements.find((element) => element.id === selectedElementId);
  const selectionReadOnly = editorReadOnly || selectedElement?.locked;
  const previewHref =
    document.id === "template-new" ? undefined : `/preview/${document.id}`;

  const patchSelectedText = (patch: Partial<TextElement>) => {
    if (!isTextElement(selectedElement) || selectionReadOnly) {
      return;
    }

    const nextElement = { ...selectedElement, ...patch };
    const shouldReflow =
      patch.fontFamily !== undefined ||
      patch.fontSize !== undefined ||
      patch.fontWeight !== undefined ||
      patch.fontStyle !== undefined ||
      patch.textDecoration !== undefined ||
      patch.align !== undefined ||
      patch.lineHeight !== undefined ||
      patch.letterSpacing !== undefined ||
      patch.wordSpacing !== undefined ||
      patch.textIndent !== undefined ||
      patch.paddingTop !== undefined ||
      patch.paddingRight !== undefined ||
      patch.paddingBottom !== undefined ||
      patch.paddingLeft !== undefined ||
      patch.wrapMode !== undefined ||
      patch.overflowMode !== undefined ||
      patch.text !== undefined;

    patchElement(selectedElement.id, {
      ...patch,
      ...(!("height" in patch) && shouldReflow
        ? {
            height: measureTextElementHeight(
              nextElement,
              nextElement.text,
              nextElement.width
            )
          }
        : {})
    });
  };

  return (
    <Box
      sx={{
        display: "grid",
        gap: 0.75,
        px: 1.25,
        py: 0.75,
        borderBottom: "1px solid rgba(15, 23, 42, 0.08)",
        background: "rgba(255, 255, 255, 0.84)",
        backdropFilter: "blur(14px)",
        "& .MuiButton-root": {
          minHeight: 30,
          px: 1,
          py: 0.35,
          fontSize: 12,
          borderRadius: 1.5
        },
        "& .MuiInputBase-root": {
          minHeight: 32,
          fontSize: 13
        },
        "& .MuiChip-root": {
          height: 24
        }
      }}
    >
        <Stack
          direction={{ xs: "column", xl: "row" }}
          spacing={1}
          sx={{
            justifyContent: "space-between",
            alignItems: { xs: "stretch", xl: "center" }
          }}
        >
        <Stack direction="row" spacing={1} sx={{ alignItems: "center", minWidth: 0 }}>
          <Button size="small" variant="outlined" onClick={onBack}>
            Voltar
          </Button>
          <Stack spacing={0.25} sx={{ minWidth: 0 }}>
            <Stack
              direction="row"
              spacing={0.75}
              useFlexGap
              sx={{ flexWrap: "wrap", alignItems: "center" }}
            >
              <TextField
                value={document.name}
                disabled={editorReadOnly}
                onChange={(event) => patchTemplate({ name: event.target.value })}
                size="small"
                sx={{ minWidth: { xs: 190, md: 260 } }}
              />
              <Chip size="small" variant="outlined" label={`v${document.version}`} />
              <Chip size="small" color="primary" variant="outlined" label={document.status} />
              <Chip
                size="small"
                variant="outlined"
                label={`${document.document.width} x ${document.document.height} ${document.document.unit}`}
              />
            </Stack>
          </Stack>
        </Stack>

        <Stack
          direction="row"
          spacing={0.75}
          useFlexGap
          sx={{ flexWrap: "wrap", justifyContent: "flex-end" }}
        >
          <Button
            variant={showLibrary ? "contained" : "outlined"}
            color={showLibrary ? "primary" : "inherit"}
            onClick={onToggleLibrary}
          >
            Biblioteca
          </Button>
          <Button
            variant={showInspector ? "contained" : "outlined"}
            color={showInspector ? "primary" : "inherit"}
            onClick={onToggleInspector}
          >
            Propriedades
          </Button>
          {!editorReadOnly ? (
            <Button variant="contained" onClick={onSave}>
              Salvar
            </Button>
          ) : null}
          {previewHref ? (
            <Button component={Link} href={previewHref} variant="outlined">
              Preview
            </Button>
          ) : (
            <Button variant="outlined" disabled>
              Preview
            </Button>
          )}
          {canPrintTest ? (
            <Button variant="outlined" onClick={onPrintTest}>
              Imprimir
            </Button>
          ) : null}
          {canPublish ? (
            <Button
              variant="contained"
              color="secondary"
              disabled={document.status !== "approved"}
              onClick={onPublish}
            >
              Publicar
            </Button>
          ) : null}
        </Stack>
      </Stack>

      <Stack direction="row" spacing={0.75} useFlexGap sx={{ flexWrap: "wrap" }}>
        <ToolbarCluster label="Documento">
          <Button variant="outlined" disabled={!canUndo} onClick={undoAction}>
            Desfazer
          </Button>
          <Button variant="outlined" disabled={!canRedo} onClick={redoAction}>
            Refazer
          </Button>
          {canCreateVersion && document.id !== "template-new" ? (
            <Button variant="outlined" onClick={onCreateVersion}>
              Nova versao
            </Button>
          ) : null}
          {canReview && document.status === "draft" && document.id !== "template-new" ? (
            <Button variant="outlined" onClick={onSubmitReview}>
              Enviar revisao
            </Button>
          ) : null}
          {canApprove && document.status === "in_review" ? (
            <>
              <Button variant="outlined" onClick={() => onApprovalDecision("rejected")}>
                Rejeitar
              </Button>
              <Button variant="outlined" onClick={() => onApprovalDecision("approved")}>
                Aprovar
              </Button>
            </>
          ) : null}
        </ToolbarCluster>

        <ToolbarCluster label="Inserir">
          {[
            { type: "text", label: "Texto" },
            { type: "barcode", label: "Codigo" },
            { type: "qrcode", label: "QR" },
            { type: "shape", label: "Retangulo" },
            { type: "line", label: "Linha" },
            { type: "image", label: "Imagem" }
          ].map((item) => (
            <Button
              key={item.label}
              variant="outlined"
              disabled={editorReadOnly}
              onClick={() => addCanvasElement(item.type as LabelElement["type"])}
            >
              {item.label}
            </Button>
          ))}
          <Button
            variant="outlined"
            disabled={editorReadOnly}
            onClick={() => addCanvasElement("text", { variant: "dynamic" })}
          >
            Campo
          </Button>
        </ToolbarCluster>

        {selectedElement ? (
          <ToolbarCluster label={selectedElement.type === "text" ? "Texto" : "Layout"}>
            <Button variant="outlined" disabled={editorReadOnly} onClick={duplicateSelectedElement}>
              Duplicar
            </Button>
            <Button
              variant={selectedElement.locked ? "contained" : "outlined"}
              disabled={editorReadOnly}
              onClick={toggleSelectedLock}
            >
              {selectedElement.locked ? "Bloqueado" : "Bloquear"}
            </Button>
            <Button variant="outlined" disabled={selectionReadOnly} onClick={() => rotateSelectedElement(-15)}>
              -15 deg
            </Button>
            <Button variant="outlined" disabled={selectionReadOnly} onClick={() => rotateSelectedElement(15)}>
              +15 deg
            </Button>
            <Button variant="outlined" disabled={selectionReadOnly} onClick={() => moveSelectedLayer("backward")}>
              Camada -
            </Button>
            <Button variant="outlined" disabled={selectionReadOnly} onClick={() => moveSelectedLayer("forward")}>
              Camada +
            </Button>
            <Button variant="outlined" disabled={selectionReadOnly} onClick={() => alignSelectedElement("center")}>
              Centro H
            </Button>
            <Button variant="outlined" disabled={selectionReadOnly} onClick={() => alignSelectedElement("middle")}>
              Centro V
            </Button>
          </ToolbarCluster>
        ) : null}

        {isTextElement(selectedElement) ? (
          <ToolbarCluster label="Tipografia">
            <TextField
              select
              size="small"
              value={selectedElement.fontFamily}
              disabled={selectionReadOnly}
              onChange={(event) =>
                patchSelectedText({ fontFamily: event.target.value })
              }
              sx={{ minWidth: 170 }}
            >
              {TEXT_FONT_OPTIONS.map((font) => (
                <MenuItem key={font.value} value={font.value}>
                  {font.label}
                </MenuItem>
              ))}
            </TextField>
            <TextField
              type="number"
              size="small"
              slotProps={{ htmlInput: { min: 6, max: 96 } }}
              value={selectedElement.fontSize}
              disabled={selectionReadOnly}
              onChange={(event) =>
                patchSelectedText({ fontSize: Number(event.target.value) })
              }
              sx={{ width: 86 }}
            />
            <Button
              variant={selectedElement.fontWeight >= 700 ? "contained" : "outlined"}
              disabled={selectionReadOnly}
              onClick={() =>
                patchSelectedText({
                  fontWeight: selectedElement.fontWeight >= 700 ? 500 : 700
                })
              }
            >
              B
            </Button>
            <Button
              variant={selectedElement.fontStyle === "italic" ? "contained" : "outlined"}
              disabled={selectionReadOnly}
              onClick={() =>
                patchSelectedText({
                  fontStyle: selectedElement.fontStyle === "italic" ? "normal" : "italic"
                })
              }
            >
              I
            </Button>
            <Button
              variant={selectedElement.align === "left" ? "contained" : "outlined"}
              disabled={selectionReadOnly}
              onClick={() => patchSelectedText({ align: "left" })}
            >
              Esq
            </Button>
            <Button
              variant={selectedElement.align === "center" ? "contained" : "outlined"}
              disabled={selectionReadOnly}
              onClick={() => patchSelectedText({ align: "center" })}
            >
              Centro
            </Button>
            <Button
              variant={selectedElement.align === "right" ? "contained" : "outlined"}
              disabled={selectionReadOnly}
              onClick={() => patchSelectedText({ align: "right" })}
            >
              Dir
            </Button>
            <Button
              variant={selectedElement.align === "justify" ? "contained" : "outlined"}
              disabled={selectionReadOnly}
              onClick={() => patchSelectedText({ align: "justify" })}
            >
              Just
            </Button>
          </ToolbarCluster>
        ) : null}

      </Stack>
    </Box>
  );
}
