"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent,
  type WheelEvent
} from "react";
import {
  type ImageElement,
  type LabelElement,
  type TextElement
} from "@easyprint/shared/template/document";
import { getBarcodeMinimumSize } from "@easyprint/shared/template/barcode";
import { buildPreviewPayload } from "@easyprint/shared/template/render";
import { useEditorStore } from "../../lib/editor-store";
import {
  EDITOR_UNIT_SCALE,
  getTextElementStyle,
  measureTextElementHeight
} from "../../lib/editor-text";
import { clampElementPositionToDocument } from "../../lib/element-movement-bounds";
import {
  getElementFrameStyle,
  LabelElementContent
} from "./document-renderer";

type InteractionMode = "move" | "resize" | "rotate";
type ResizeHandle = "n" | "ne" | "e" | "se" | "s" | "sw" | "w" | "nw";
const MIN_ZOOM = 0.35;
const MAX_ZOOM = 3;
const IMAGE_MIN_SIZE = 3;
const QRCODE_MIN_SIZE = 8;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const toFreeMovementValue = (value: number) => Number(value.toFixed(3));

const isTextElement = (element: LabelElement | undefined): element is TextElement =>
  Boolean(element && element.type === "text");

const isImageElement = (element: LabelElement | undefined): element is ImageElement =>
  Boolean(element && element.type === "image");

const getElementMinimumSize = (element: LabelElement) => {
  if (element.type === "barcode") {
    const barcodeMinimum = getBarcodeMinimumSize(element.format);
    return {
      minWidth: barcodeMinimum.widthMm,
      minHeight: barcodeMinimum.heightMm
    };
  }

  if (element.type === "qrcode") {
    return {
      minWidth: QRCODE_MIN_SIZE,
      minHeight: QRCODE_MIN_SIZE
    };
  }

  if (element.type === "image") {
    return {
      minWidth: IMAGE_MIN_SIZE,
      minHeight: IMAGE_MIN_SIZE
    };
  }

  if (element.type === "line") {
    return {
      minWidth: 4,
      minHeight: Math.max(0.2, element.strokeWidth || 0.2)
    };
  }

  return {
    minWidth: 4,
    minHeight: 4
  };
};

const resizeHandles: Array<{
  handle: ResizeHandle;
  cursor: string;
  style: CSSProperties;
}> = [
  { handle: "nw", cursor: "nwse-resize", style: { left: -6, top: -6 } },
  { handle: "n", cursor: "ns-resize", style: { left: "50%", top: -6, transform: "translateX(-50%)" } },
  { handle: "ne", cursor: "nesw-resize", style: { right: -6, top: -6 } },
  { handle: "e", cursor: "ew-resize", style: { right: -6, top: "50%", transform: "translateY(-50%)" } },
  { handle: "se", cursor: "nwse-resize", style: { right: -6, bottom: -6 } },
  { handle: "s", cursor: "ns-resize", style: { left: "50%", bottom: -6, transform: "translateX(-50%)" } },
  { handle: "sw", cursor: "nesw-resize", style: { left: -6, bottom: -6 } },
  { handle: "w", cursor: "ew-resize", style: { left: -6, top: "50%", transform: "translateY(-50%)" } }
];

export function EditorCanvas({ readOnly = false }: { readOnly?: boolean }) {
  const {
    history,
    selectedElementId,
    selectElement,
    patchElement,
    zoom,
    setZoom,
    gridEnabled,
    snapEnabled,
    gridSize,
    markStatus
  } = useEditorStore();
  const document = history.present;
  const previewPayload = useMemo(() => buildPreviewPayload(document), [document]);
  const viewportRef = useRef<HTMLDivElement | null>(null);
  const textEditorRef = useRef<HTMLTextAreaElement | null>(null);
  const lastZoomRef = useRef(zoom);
  const [spacePressed, setSpacePressed] = useState(false);
  const [dragState, setDragState] = useState<{
    id: string;
    mode: InteractionMode;
    handle?: ResizeHandle;
    pointerId: number;
    startClientX: number;
    startClientY: number;
    startElementX: number;
    startElementY: number;
    startElementWidth: number;
    startElementHeight: number;
    startRotation: number;
    startPointerAngle: number;
    centerClientX: number;
    centerClientY: number;
    maintainAspectRatio: boolean;
  } | null>(null);
  const [panState, setPanState] = useState<{
    startX: number;
    startY: number;
    scrollLeft: number;
    scrollTop: number;
  } | null>(null);
  const [textEditor, setTextEditor] = useState<{
    id: string;
    value: string;
  } | null>(null);

  const stageScale = EDITOR_UNIT_SCALE * zoom;

  const autosizeTextarea = useCallback(() => {
    if (!textEditorRef.current) {
      return;
    }

    textEditorRef.current.style.height = "auto";
    textEditorRef.current.style.height = `${textEditorRef.current.scrollHeight}px`;
  }, []);

  useEffect(() => {
    if (!textEditorRef.current) {
      return;
    }

    textEditorRef.current.focus();
    textEditorRef.current.setSelectionRange(
      textEditorRef.current.value.length,
      textEditorRef.current.value.length
    );
    autosizeTextarea();
  }, [autosizeTextarea, textEditor]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.code === "Space" && !(event.target instanceof HTMLInputElement) && !(event.target instanceof HTMLTextAreaElement) && !(event.target instanceof HTMLSelectElement)) {
        event.preventDefault();
        setSpacePressed(true);
      }
    };

    const handleKeyUp = (event: KeyboardEvent) => {
      if (event.code === "Space") {
        setSpacePressed(false);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
    };
  }, []);

  useEffect(() => {
    if (selectedElementId !== textEditor?.id) {
      setTextEditor(null);
    }
  }, [selectedElementId, textEditor?.id]);

  useEffect(() => {
    const viewport = viewportRef.current;
    const previousZoom = lastZoomRef.current;
    if (!viewport || previousZoom === zoom) {
      lastZoomRef.current = zoom;
      return;
    }

    const ratioX =
      viewport.scrollWidth > viewport.clientWidth
        ? viewport.scrollLeft / Math.max(1, viewport.scrollWidth - viewport.clientWidth)
        : 0.5;
    const ratioY =
      viewport.scrollHeight > viewport.clientHeight
        ? viewport.scrollTop / Math.max(1, viewport.scrollHeight - viewport.clientHeight)
        : 0.5;

    requestAnimationFrame(() => {
      viewport.scrollLeft = Math.max(
        0,
        ratioX * Math.max(0, viewport.scrollWidth - viewport.clientWidth)
      );
      viewport.scrollTop = Math.max(
        0,
        ratioY * Math.max(0, viewport.scrollHeight - viewport.clientHeight)
      );
    });

    lastZoomRef.current = zoom;
  }, [zoom]);

  const commitTextEditor = useCallback(() => {
    if (!textEditor) {
      return;
    }

    const target = document.elements.find((element) => element.id === textEditor.id);
    if (!isTextElement(target) || target.contentMode !== "static") {
      setTextEditor(null);
      return;
    }

    const nextHeight = measureTextElementHeight(target, textEditor.value, target.width);
    patchElement(target.id, {
      text: textEditor.value,
      height: nextHeight
    });
    markStatus("Texto atualizado");
    setTextEditor(null);
  }, [document.elements, markStatus, patchElement, textEditor]);

  const cancelTextEditor = useCallback(() => {
    setTextEditor(null);
    markStatus("Edicao de texto cancelada");
  }, [markStatus]);

  const handleViewportWheel = (event: WheelEvent<HTMLDivElement>) => {
    if (!(event.ctrlKey || event.metaKey)) {
      return;
    }

    event.preventDefault();
    const nextZoom = clamp(
      Number((zoom * (event.deltaY < 0 ? 1.08 : 0.92)).toFixed(2)),
      MIN_ZOOM,
      MAX_ZOOM
    );

    if (nextZoom === zoom) {
      return;
    }

    const viewport = viewportRef.current;
    if (!viewport) {
      setZoom(nextZoom);
      return;
    }

    const rect = viewport.getBoundingClientRect();
    const pointerX = event.clientX - rect.left;
    const pointerY = event.clientY - rect.top;
    const anchorX = viewport.scrollLeft + pointerX;
    const anchorY = viewport.scrollTop + pointerY;
    const ratio = nextZoom / zoom;

    setZoom(nextZoom);

    requestAnimationFrame(() => {
      viewport.scrollLeft = anchorX * ratio - pointerX;
      viewport.scrollTop = anchorY * ratio - pointerY;
    });
  };

  const startInteraction = (
    event: PointerEvent<HTMLDivElement>,
    element: LabelElement,
    mode: InteractionMode,
    handle?: ResizeHandle
  ) => {
    event.stopPropagation();
    event.preventDefault();
    selectElement(element.id);

    if (readOnly || element.locked || event.button !== 0) {
      return;
    }

    const viewport = viewportRef.current;
    if (viewport) {
      viewport.setPointerCapture(event.pointerId);
    }

    const surface = viewport?.querySelector<HTMLDivElement>(".editor-canvas-surface");
    const surfaceRect = surface?.getBoundingClientRect();
    const centerClientX = surfaceRect
      ? surfaceRect.left + (element.x + element.width / 2) * stageScale
      : event.clientX;
    const centerClientY = surfaceRect
      ? surfaceRect.top + (element.y + element.height / 2) * stageScale
      : event.clientY;

    setDragState({
      id: element.id,
      mode,
      handle,
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      startElementX: element.x,
      startElementY: element.y,
      startElementWidth: element.width,
      startElementHeight: element.height,
      startRotation: element.rotation,
      startPointerAngle: Math.atan2(event.clientY - centerClientY, event.clientX - centerClientX),
      centerClientX,
      centerClientY,
      maintainAspectRatio: isImageElement(element) ? element.maintainAspectRatio ?? true : false
    });
  };

  const startTextEditing = (element: LabelElement) => {
    if (
      readOnly ||
      element.locked ||
      element.type !== "text" ||
      element.contentMode !== "static"
    ) {
      return;
    }

    selectElement(element.id);
    setTextEditor({ id: element.id, value: element.text });
  };

  const handleViewportPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (
      event.button === 1 ||
      (spacePressed && event.button === 0)
    ) {
      const viewport = viewportRef.current;
      if (!viewport) {
        return;
      }

      event.preventDefault();
      setPanState({
        startX: event.clientX,
        startY: event.clientY,
        scrollLeft: viewport.scrollLeft,
        scrollTop: viewport.scrollTop
      });
      return;
    }

    if (event.target === event.currentTarget) {
      selectElement(undefined);
    }
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (panState) {
      event.preventDefault();
      const viewport = viewportRef.current;
      if (!viewport) {
        return;
      }

      viewport.scrollLeft = panState.scrollLeft - (event.clientX - panState.startX);
      viewport.scrollTop = panState.scrollTop - (event.clientY - panState.startY);
      return;
    }

    if (!dragState) {
      return;
    }

    const dx = (event.clientX - dragState.startClientX) / stageScale;
    const dy = (event.clientY - dragState.startClientY) / stageScale;
    const effectiveSnapSize =
      gridEnabled && snapEnabled
        ? event.altKey
          ? Math.max(0.25, gridSize / 4)
          : Math.max(1, gridSize)
        : null;
    const resolveDelta = (value: number) =>
      effectiveSnapSize
        ? Math.round(value / effectiveSnapSize) * effectiveSnapSize
        : toFreeMovementValue(value);

    if (dragState.mode === "move") {
      const nextX = dragState.startElementX + resolveDelta(dx);
      const nextY = dragState.startElementY + resolveDelta(dy);
      const boundedPosition = clampElementPositionToDocument(
        nextX,
        nextY,
        {
          width: dragState.startElementWidth,
          height: dragState.startElementHeight,
          rotation: dragState.startRotation
        },
        document.document.width,
        document.document.height
      );

      patchElement(dragState.id, {
        x: toFreeMovementValue(boundedPosition.x),
        y: toFreeMovementValue(boundedPosition.y)
      });
      return;
    }

    const selectedElement = document.elements.find((element) => element.id === dragState.id);
    if (dragState.mode === "rotate") {
      const currentAngle = Math.atan2(
        event.clientY - dragState.centerClientY,
        event.clientX - dragState.centerClientX
      );
      const deltaDegrees = (currentAngle - dragState.startPointerAngle) * (180 / Math.PI);
      const rawRotation = dragState.startRotation + deltaDegrees;
      const nextRotation = event.shiftKey ? Math.round(rawRotation / 15) * 15 : rawRotation;

      patchElement(dragState.id, {
        rotation: Number(nextRotation.toFixed(2))
      });
      return;
    }

    if (!selectedElement) {
      return;
    }

    const { minWidth, minHeight } = getElementMinimumSize(selectedElement);
    const handle = dragState.handle ?? "se";
    const deltaX = resolveDelta(dx);
    const deltaY = resolveDelta(dy);
    let left = dragState.startElementX;
    let top = dragState.startElementY;
    let right = dragState.startElementX + dragState.startElementWidth;
    let bottom = dragState.startElementY + dragState.startElementHeight;

    if (handle.includes("w")) left += deltaX;
    if (handle.includes("e")) right += deltaX;
    if (handle.includes("n")) top += deltaY;
    if (handle.includes("s")) bottom += deltaY;

    const isCornerResize = handle.length === 2;
    const shouldKeepAspect =
      selectedElement.type === "image" &&
      isCornerResize &&
      (dragState.maintainAspectRatio ? !event.shiftKey : event.shiftKey);

    if (shouldKeepAspect) {
      const startAspect =
        dragState.startElementWidth / Math.max(minHeight, dragState.startElementHeight);
      const nextWidth = Math.max(minWidth, right - left);
      const nextHeight = Math.max(minHeight, bottom - top);
      const widthDriven = Math.abs(nextWidth - dragState.startElementWidth) >=
        Math.abs(nextHeight - dragState.startElementHeight);
      const adjustedWidth = widthDriven ? nextWidth : nextHeight * startAspect;
      const adjustedHeight = widthDriven ? nextWidth / startAspect : nextHeight;

      if (handle.includes("w")) left = right - adjustedWidth;
      else right = left + adjustedWidth;

      if (handle.includes("n")) top = bottom - adjustedHeight;
      else bottom = top + adjustedHeight;
    }

    if (right - left < minWidth) {
      if (handle.includes("w")) left = right - minWidth;
      else right = left + minWidth;
    }

    if (bottom - top < minHeight) {
      if (handle.includes("n")) top = bottom - minHeight;
      else bottom = top + minHeight;
    }

    left = clamp(left, 0, Math.max(0, document.document.width - minWidth));
    top = clamp(top, 0, Math.max(0, document.document.height - minHeight));
    right = clamp(right, left + minWidth, document.document.width);
    bottom = clamp(bottom, top + minHeight, document.document.height);

    patchElement(dragState.id, {
      x: toFreeMovementValue(left),
      y: toFreeMovementValue(top),
      width: toFreeMovementValue(right - left),
      height: toFreeMovementValue(bottom - top)
    });
  };

  const handlePointerFinish = () => {
    if (dragState) {
      const viewport = viewportRef.current;
      if (viewport?.hasPointerCapture(dragState.pointerId)) {
        viewport.releasePointerCapture(dragState.pointerId);
      }
    }
    setDragState(null);
    setPanState(null);
  };

  const selectedElement = document.elements.find((element) => element.id === selectedElementId);

  return (
    <div
      ref={viewportRef}
      className="editor-canvas-viewport"
      onWheel={handleViewportWheel}
      onPointerDown={handleViewportPointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerFinish}
      onPointerLeave={handlePointerFinish}
      onClick={(event) => {
        if (!panState && event.target === event.currentTarget) {
          selectElement(undefined);
        }
      }}
      style={{
        minHeight: 0,
        height: "100%",
        overflow: "auto",
        overscrollBehavior: "contain",
        cursor: panState ? "grabbing" : spacePressed ? "grab" : "default"
      }}
    >
      <div
        className="editor-canvas-workspace"
        style={{
          minWidth: "100%",
          minHeight: "100%",
          display: "grid",
          justifyItems: "center",
          alignItems: "start",
          alignContent: "start",
          padding: "18px 48px 64px"
        }}
      >
        <div
          className="editor-canvas-surface"
          style={{
            position: "relative",
            width: document.document.width * stageScale,
            height: document.document.height * stageScale,
            background: document.document.background,
            borderRadius: 14,
            boxShadow: "0 22px 48px rgba(15, 23, 42, 0.16)",
            overflow: "hidden",
            backgroundImage: gridEnabled
              ? "linear-gradient(rgba(15,23,42,0.045) 1px, transparent 1px), linear-gradient(90deg, rgba(15,23,42,0.045) 1px, transparent 1px)"
              : undefined,
            backgroundSize: gridEnabled
              ? `${gridSize * stageScale}px ${gridSize * stageScale}px`
              : undefined
          }}
        >
          {[...document.elements]
            .sort((left, right) => left.zIndex - right.zIndex)
            .map((element) => {
              const selected = element.id === selectedElementId;
              const isEditing = textEditor?.id === element.id;

              return (
                <div
                  key={element.id}
                  style={getElementFrameStyle(element, stageScale, false, {
                    border: selected ? "1px solid #0f766e" : "1px solid transparent",
                    outline: selected ? "2px solid rgba(15, 118, 110, 0.18)" : "none",
                    borderRadius: 10,
                    cursor: readOnly ? "default" : element.locked ? "not-allowed" : "move",
                    userSelect: "none"
                  })}
                  onPointerDown={(event) => startInteraction(event, element, "move")}
                  onClick={(event) => {
                    event.stopPropagation();
                    selectElement(element.id);
                  }}
                  onDoubleClick={() => startTextEditing(element)}
                >
                  {isEditing && isTextElement(element) ? (
                    <textarea
                      ref={textEditorRef}
                      value={textEditor.value}
                      onChange={(event) => {
                        setTextEditor({ id: element.id, value: event.target.value });
                        autosizeTextarea();
                      }}
                      onBlur={commitTextEditor}
                      onClick={(event) => event.stopPropagation()}
                      onPointerDown={(event) => event.stopPropagation()}
                      onKeyDown={(event: ReactKeyboardEvent<HTMLTextAreaElement>) => {
                        if (event.key === "Escape") {
                          event.preventDefault();
                          cancelTextEditor();
                        }

                        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
                          event.preventDefault();
                          commitTextEditor();
                        }
                      }}
                      style={{
                        ...getTextElementStyle(element, stageScale),
                        minHeight: "100%",
                        resize: "none",
                        border: "none",
                        outline: "none",
                        padding: 0,
                        background: "rgba(255,255,255,0.86)",
                        overflow: "hidden"
                      }}
                    />
                  ) : (
                    <LabelElementContent
                      document={document}
                      element={element}
                      scale={stageScale}
                      previewPayload={previewPayload}
                    />
                  )}

                  {element.locked ? (
                    <div
                      style={{
                        position: "absolute",
                        top: -12,
                        right: -12,
                        padding: "3px 8px",
                        borderRadius: 999,
                        background: "#0f172a",
                        color: "#fff",
                        fontSize: 10,
                        fontWeight: 600
                      }}
                    >
                      Lock
                    </div>
                  ) : null}

                  {selected && !readOnly && !element.locked ? (
                    <>
                      <div
                        style={{
                          position: "absolute",
                          left: "50%",
                          top: -36,
                          width: 1,
                          height: 28,
                          background: "rgba(15, 118, 110, 0.58)",
                          transform: "translateX(-50%)",
                          pointerEvents: "none"
                        }}
                      />
                      <div
                        onPointerDown={(event) => startInteraction(event, element, "rotate")}
                        title={`${Math.round(element.rotation)} graus`}
                        style={{
                          position: "absolute",
                          left: "50%",
                          top: -46,
                          width: 18,
                          height: 18,
                          background: "#ffffff",
                          border: "2px solid #0f766e",
                          boxShadow: "0 5px 14px rgba(15, 23, 42, 0.22)",
                          borderRadius: 999,
                          cursor: "grab",
                          transform: "translateX(-50%)"
                        }}
                      />
                      <div
                        style={{
                          position: "absolute",
                          left: "50%",
                          top: -68,
                          transform: "translateX(-50%)",
                          padding: "2px 6px",
                          borderRadius: 999,
                          background: "#0f172a",
                          color: "#ffffff",
                          fontSize: 10,
                          fontWeight: 700,
                          lineHeight: 1,
                          pointerEvents: "none",
                          whiteSpace: "nowrap"
                        }}
                      >
                        {Math.round(element.rotation)} graus
                      </div>
                      {resizeHandles.map((resizeHandle) => (
                        <div
                          key={resizeHandle.handle}
                          onPointerDown={(event) =>
                            startInteraction(event, element, "resize", resizeHandle.handle)
                          }
                          style={{
                            position: "absolute",
                            width: 13,
                            height: 13,
                            background: "#ffffff",
                            border: "2px solid #0f766e",
                            boxShadow: "0 4px 10px rgba(15, 23, 42, 0.18)",
                            borderRadius: resizeHandle.handle.length === 2 ? 999 : 4,
                            cursor: resizeHandle.cursor,
                            ...resizeHandle.style
                          }}
                        />
                      ))}
                    </>
                  ) : null}
                </div>
              );
            })}
        </div>
      </div>

      <div
        className="muted"
        style={{
          position: "sticky",
          left: 20,
          bottom: 20,
          width: "fit-content",
          padding: "7px 11px",
          borderRadius: 999,
          background: "rgba(255,255,255,0.76)",
          border: "1px solid var(--line)",
          backdropFilter: "blur(10px)",
          margin: "0 0 20px 20px",
          fontSize: 12
        }}
      >
        {selectedElement
          ? `Duplo clique para editar texto, Ctrl/Cmd + roda para zoom, Space + arrastar para pan, Alt para ajuste fino com grade`
          : "Ctrl/Cmd + roda para zoom, Space + arrastar para pan, Alt para ajuste fino"}
      </div>
    </div>
  );
}
