export const getDefaultLabelFormat = (): LabelFormat => LABEL_FORMATS[0]!;

export const getLabelFormatById = (id: string | null | undefined): LabelFormat | undefined =>
  LABEL_FORMATS.find((format) => format.id === id);

export const findLabelFormatByDimensions = (
  widthMm: number,
  heightMm: number
): LabelFormat | undefined =>
  LABEL_FORMATS.find(
    (format) => format.widthMm === widthMm && format.heightMm === heightMm
  ) ??
  LABEL_FORMATS.find(
    (format) => format.widthMm === heightMm && format.heightMm === widthMm
  );

export const listFormatsByCategory = (categoryId: string) =>
  LABEL_FORMATS.filter((format) => format.category === categoryId);

export const listFormats = () => LABEL_FORMATS;
