"use client";

import { useMemo, useState } from "react";
import { SessionGuard } from "../../../components/app/session-guard";
import { DashboardShell } from "../../../components/app/dashboard-shell";
import { LabelPreviewSurface } from "../../../components/editor/label-preview-surface";
import { EditorShell } from "../../../components/editor/editor-shell";
import {
  buildOfficialTemplateDocument,
  buildOfficialTemplatePreviewPayload,
  listOfficialTemplatePresetOptions
} from "../../../lib/official-template-presets";
import type { OfficialTemplateId } from "../../../lib/official-template-catalog";
import { sessionHasPermission, type ApiSession } from "../../../lib/session";

const PRESET_OPTIONS = listOfficialTemplatePresetOptions();
const FIRST_TEMPLATE_ID = PRESET_OPTIONS[0]?.id ?? "vertical_unit_basic";

export default function NewTemplatePage() {
  const [session, setSession] = useState<ApiSession | null>(null);
  const [createdTemplateId, setCreatedTemplateId] = useState<OfficialTemplateId | null>(null);
  const [selectedTemplateId, setSelectedTemplateId] =
    useState<OfficialTemplateId>(FIRST_TEMPLATE_ID as OfficialTemplateId);
  const [selectedFormatId, setSelectedFormatId] = useState(
    PRESET_OPTIONS[0]?.defaultFormat?.id ?? ""
  );
  const [selectedOrientation, setSelectedOrientation] = useState<"portrait" | "landscape">(
    PRESET_OPTIONS[0]?.orientation ?? "portrait"
  );

  const canViewTemplates = sessionHasPermission(session, "template.view");
  const canEditTemplates = sessionHasPermission(session, "template.edit");

  const selectedPreset = useMemo(
    () => PRESET_OPTIONS.find((preset) => preset.id === selectedTemplateId) ?? PRESET_OPTIONS[0],
    [selectedTemplateId]
  );

  const previewDocument = useMemo(() => {
    if (!selectedPreset) {
      return null;
    }

    return buildOfficialTemplateDocument({
      templateId: selectedTemplateId,
      formatId: selectedFormatId || selectedPreset.defaultFormat?.id,
      orientation: selectedOrientation
    });
  }, [selectedFormatId, selectedOrientation, selectedPreset, selectedTemplateId]);

  const createdDocument = useMemo(() => {
    if (!createdTemplateId || createdTemplateId !== selectedTemplateId || !previewDocument) {
      return null;
    }

    return previewDocument;
  }, [createdTemplateId, previewDocument, selectedTemplateId]);

  const handleTemplateSelection = (templateId: OfficialTemplateId) => {
    const nextPreset = PRESET_OPTIONS.find((preset) => preset.id === templateId);
    if (!nextPreset) {
      return;
    }

    setSelectedTemplateId(templateId);
    setSelectedFormatId(nextPreset.defaultFormat?.id ?? nextPreset.recommendedFormats[0]?.id ?? "");
    setSelectedOrientation(nextPreset.orientation);
  };

  return (
    <SessionGuard onSession={setSession}>
      {!canViewTemplates || !canEditTemplates ? (
        <main className="shell">
          <div className="panel" style={{ padding: 24 }}>
            Seu papel atual nao possui acesso a criacao guiada de templates.
          </div>
        </main>
      ) : createdDocument ? (
        <EditorShell initialDocument={createdDocument} />
      ) : (
        <DashboardShell
          title="Novo Template"
          subtitle="Escolha o tipo de etiqueta antes de abrir o editor. O template nasce com layout, campos e formato coerentes com a operacao."
        >
          <div className="template-wizard">
            <section className="panel template-wizard__hero">
              <div className="template-wizard__eyebrow">Fluxo guiado obrigatorio</div>
              <h2 className="template-wizard__title">
                O EasyPrint agora cria templates a partir de tipos oficiais de etiqueta.
              </h2>
              <p className="template-wizard__subtitle">
                Em vez de abrir um canvas vazio sem contexto, escolha a familia do layout, o formato
                fisico e a orientacao. O editor abre com estrutura real de produto.
              </p>
            </section>

            <section className="template-wizard__layout">
              <aside className="panel template-wizard__catalog">
                <div className="template-wizard__section-header">
                  <strong>1. Tipo de etiqueta</strong>
                  <p className="muted">
                    Essa escolha passa a ser obrigatoria e orienta campos, estrutura e formato inicial.
                  </p>
                </div>

                <div className="template-wizard__template-list">
                  {PRESET_OPTIONS.map((preset) => (
                    <button
                      key={preset.id}
                      type="button"
                      className={`template-wizard__template-card ${preset.id === selectedTemplateId ? "is-active" : ""}`}
                      onClick={() => handleTemplateSelection(preset.id as OfficialTemplateId)}
                    >
                      <div className="template-wizard__template-meta">
                        <span className="template-wizard__template-kind">
                          {preset.operationKind === "unit" ? "Por unidade" : "Por peso"}
                        </span>
                        <span className="template-wizard__template-kind">
                          {preset.orientation === "portrait" ? "Vertical" : "Horizontal"}
                        </span>
                      </div>
                      <strong>{preset.name}</strong>
                      <div className="muted">{preset.summary}</div>
                    </button>
                  ))}
                </div>
              </aside>

              <section className="panel template-wizard__workbench">
                <div className="template-wizard__controls">
                  <div className="template-wizard__section-header">
                    <strong>2. Formato e orientacao</strong>
                    <p className="muted">
                      O formato fisico recomendado vem preenchido, mas voce pode escolher outro antes de abrir o editor.
                    </p>
                  </div>

                  <div className="template-wizard__form-grid">
                    <label className="template-wizard__field">
                      <span className="template-wizard__label">Formato / tamanho</span>
                      <select
                        value={selectedFormatId}
                        onChange={(event) => setSelectedFormatId(event.target.value)}
                      >
                        {selectedPreset?.recommendedFormats.map((format) => (
                          <option key={format.id} value={format.id}>
                            {format.name} · {format.widthMm} x {format.heightMm} mm
                          </option>
                        ))}
                      </select>
                    </label>

                    <label className="template-wizard__field">
                      <span className="template-wizard__label">Orientacao</span>
                      <select
                        value={selectedOrientation}
                        onChange={(event) =>
                          setSelectedOrientation(event.target.value as "portrait" | "landscape")
                        }
                      >
                        <option value="portrait">Vertical</option>
                        <option value="landscape">Horizontal</option>
                      </select>
                    </label>
                  </div>

                  <div className="template-wizard__summary">
                    <strong>{selectedPreset?.name}</strong>
                    <div className="muted">
                      {selectedPreset?.summary}
                    </div>
                  </div>

                  <div className="template-wizard__actions">
                    <button
                      type="button"
                      className="template-wizard__primary"
                      disabled={!previewDocument}
                      onClick={() => setCreatedTemplateId(selectedTemplateId)}
                    >
                      Criar template com este tipo
                    </button>
                    <div className="muted">
                      O editor so abre depois da selecao do tipo de etiqueta.
                    </div>
                  </div>
                </div>

                <div className="template-wizard__preview">
                  <div className="template-wizard__section-header">
                    <strong>3. Estrutura inicial</strong>
                    <p className="muted">
                      Preview do documento base que sera aberto no editor. O renderer e o mesmo do preview e da impressao.
                    </p>
                  </div>

                  <div className="template-wizard__preview-stage">
                    {previewDocument ? (
                      <LabelPreviewSurface
                        document={previewDocument}
                        previewPayload={buildOfficialTemplatePreviewPayload(selectedTemplateId)}
                        scale={Math.min(
                          4.8,
                          380 / Math.max(previewDocument.document.width, 1),
                          360 / Math.max(previewDocument.document.height, 1)
                        )}
                        preset="preview"
                      />
                    ) : null}
                  </div>
                </div>
              </section>
            </section>
          </div>
        </DashboardShell>
      )}
    </SessionGuard>
  );
}
